'use client';

import { useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { User } from 'lucide-react';
import { toast } from 'sonner';
import { Input } from '@/src/components/ui/input';
import { Label } from '@/src/components/ui/label';
import { Textarea } from '@/src/components/ui/textarea';
import { Badge } from '@/src/components/ui/badge';
import { SettingsPageShell } from '@/src/components/settings/SettingsPageShell';
import { SettingsSection } from '@/src/components/enterprise/SettingsSection';
import { useAuth } from '@/src/context/AuthContext';
import { apiFetch } from '@/src/lib/api/api-client';

export default function SettingsProfilePage() {
  const t = useTranslations('Settings');
  const { user, refreshUser } = useAuth();
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [bio, setBio] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (user) {
      setName(user.name || '');
      setPhone(user.phone || '');
      setBio(user.bio || '');
    }
  }, [user]);

  const kycStatus = user?.kycStatus ?? 'unverified';
  const kycLabel =
    kycStatus === 'verified'
      ? t('account.verified')
      : kycStatus === 'pending'
        ? t('account.pending')
        : t('account.unverified');

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const parts = name.trim().split(/\s+/);
      const firstName = parts[0] || '';
      const lastName = parts.slice(1).join(' ');
      await apiFetch('/auth/me', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ first_name: firstName, last_name: lastName, phone, bio }),
      });
      await refreshUser?.();
      toast.success(t('success'));
    } catch {
      toast.error(t('error'));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <SettingsPageShell onSave={handleSave} isSaving={isSaving} showSave>
      <SettingsSection
        title={t('account.title')}
        description={t('account.subtitle')}
        icon={<User className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="rounded-lg border border-border bg-muted/30 p-4">
            <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
              {t('account.signedInAs')}
            </p>
            <p className="mt-1 text-sm font-semibold text-foreground">{user?.email}</p>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2 sm:col-span-2">
              <Label htmlFor="profile-name">{t('account.fullName', { defaultValue: 'Full name' })}</Label>
              <Input id="profile-name" value={name} onChange={(e) => setName(e.target.value)} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="profile-phone">{t('account.phone', { defaultValue: 'Phone' })}</Label>
              <Input id="profile-phone" value={phone} onChange={(e) => setPhone(e.target.value)} />
            </div>
            <div className="space-y-2 flex items-end">
              <div>
                <p className="text-sm font-medium">{t('account.verificationStatus')}</p>
                <Badge variant={kycStatus === 'verified' ? 'default' : 'secondary'} className="mt-1 capitalize">
                  {kycLabel}
                </Badge>
              </div>
            </div>
            <div className="space-y-2 sm:col-span-2">
              <Label htmlFor="profile-bio">{t('account.bio', { defaultValue: 'Bio' })}</Label>
              <Textarea id="profile-bio" value={bio} onChange={(e) => setBio(e.target.value)} rows={3} />
            </div>
          </div>
        </div>
      </SettingsSection>
    </SettingsPageShell>
  );
}
